<template>
<section class="space-y-8">
<div><p class="font-bold text-indigo-600">MANAGEMENT</p><h1 class="mt-2 text-4xl font-black">Catalog & inventory</h1><p class="mt-2 text-slate-500">Manage the company catalog, variants, brands, warehouses, suppliers and stock.</p></div>
<div class="flex flex-wrap gap-2 border-b pb-3"><button v-for="t in tabs" :key="t" @click="tab=t" :class="['rounded-xl px-4 py-2 text-sm font-bold',tab===t?'bg-slate-950 text-white':'bg-white border']">{{t}}</button></div>
<div v-if="tab==='Product'" class="rounded-2xl border bg-white p-6">
<h2 class="text-xl font-black">Create product</h2><div class="mt-5 grid gap-4 md:grid-cols-2">
<input v-model="form.name" class="rounded-xl border p-3" placeholder="Product name"/>
<select v-model="form.categoryId" @change="loadCategoryAttributes" class="rounded-xl border p-3"><option value="">Category</option><option v-for="c in categories" :value="c.id">{{c.name}}</option></select>
<select v-model="form.brandId" class="rounded-xl border p-3"><option value="">Brand (optional)</option><option v-for="b in brands" :value="b.id">{{b.name}}</option></select>
<input v-model.number="form.price" type="number" class="rounded-xl border p-3" placeholder="Base price"/>
<input v-model="form.sku" class="rounded-xl border p-3" placeholder="Base SKU"/>
<input v-model="form.imageUrl" class="rounded-xl border p-3" placeholder="Image URL"/>
</div><textarea v-model="form.description" class="mt-4 w-full rounded-xl border p-3" rows="3" placeholder="Description"></textarea>
<div class="mt-7 rounded-2xl bg-slate-50 p-4"><div class="flex items-center justify-between"><div><h3 class="font-black">Category attributes</h3><p class="text-xs text-slate-500">Mark attributes as variant options such as Color or Size.</p></div></div>
<div v-for="o in optionForms" :key="o.attributeId" class="mt-4 rounded-xl border bg-white p-4"><div class="flex items-center gap-3"><b>{{o.name}}</b><label class="ml-auto text-sm"><input type="checkbox" v-model="o.isVariant"/> Variant option</label></div><input v-model="o.valuesText" class="mt-3 w-full rounded-lg border p-2" :placeholder="'Values: '+(o.sample||'Black, White, Red')"/></div>
<p v-if="!optionForms.length" class="mt-3 text-sm text-slate-400">Select a category to load its attribute rules.</p></div>
<div class="mt-7 flex items-center justify-between"><h3 class="font-black">Generated variants</h3><button @click="generateVariants" class="rounded-xl border px-4 py-2 font-bold">Generate combinations</button></div>
<div v-if="variants.length" class="mt-3 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-2">Options</th><th class="p-2">SKU</th><th class="p-2">Price</th><th class="p-2">Warehouse</th><th class="p-2">Opening stock</th></tr></thead><tbody><tr v-for="(v,i) in variants" :key="i" class="border-b"><td class="p-2">{{v.label}}</td><td class="p-2"><input v-model="v.sku" class="w-32 rounded border p-2"/></td><td class="p-2"><input v-model.number="v.price" type="number" class="w-28 rounded border p-2"/></td><td class="p-2"><select v-model="v.warehouseId" class="rounded border p-2"><option value="">Select</option><option v-for="w in warehouses" :value="w.id">{{w.name}}</option></select></td><td class="p-2"><input v-model.number="v.quantity" type="number" min="0" class="w-24 rounded border p-2"/></td></tr></tbody></table></div>
<button @click="createProduct" :disabled="busy" class="mt-6 rounded-xl bg-indigo-600 px-5 py-3 font-bold text-white disabled:opacity-50">{{busy?'Saving…':'Create product & variants'}}</button><p v-if="message" class="mt-3 text-sm">{{message}}</p>
</div>
<div v-if="tab==='Inventory'" class="grid gap-6 lg:grid-cols-2">
<div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Stock adjustment</h2><div class="mt-4 space-y-3"><select v-model="adjust.warehouseId" class="w-full rounded-xl border p-3"><option value="">Warehouse</option><option v-for="w in warehouses" :value="w.id">{{w.name}}</option></select><select v-model="adjust.variantId" class="w-full rounded-xl border p-3"><option value="">Product variant</option><option v-for="v in allVariants" :value="v.id">{{v.product?.name}} · {{v.sku}}</option></select><select v-model="adjust.type" class="w-full rounded-xl border p-3"><option value="receive">Receive stock</option><option value="adjustment_in">Adjustment in</option><option value="adjustment_out">Adjustment out</option><option value="damage">Damage</option></select><input v-model.number="adjust.quantity" type="number" min="1" class="w-full rounded-xl border p-3" placeholder="Quantity"/><input v-model="adjust.note" class="w-full rounded-xl border p-3" placeholder="Reason / note"/><button @click="adjustStock" class="w-full rounded-xl bg-slate-950 py-3 font-bold text-white">Save stock movement</button></div></div>
<div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Current inventory</h2><div class="mt-4 space-y-2"><div v-for="x in inventory" :key="x.id" class="flex items-center justify-between rounded-xl bg-slate-50 p-3"><div><b>{{x.variant?.product?.name}}</b><p class="text-xs text-slate-500">{{x.variant?.sku}} · {{x.warehouse?.name}}</p></div><div class="text-right"><b>{{x.quantityOnHand}}</b><p class="text-xs text-slate-500">reserved {{x.reservedQuantity}}</p></div></div></div></div>
</div>
<div v-if="tab==='Brands'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Brands</h2><div class="mt-4 flex gap-3"><input v-model="brandName" class="flex-1 rounded-xl border p-3" placeholder="Brand name"/><button @click="createBrand" class="rounded-xl bg-slate-950 px-5 font-bold text-white">Add brand</button></div><div class="mt-4 flex flex-wrap gap-2"><span v-for="b in brands" class="rounded-full bg-slate-100 px-3 py-2 text-sm font-bold">{{b.name}}</span></div></div>
<div v-if="tab==='Warehouses'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Warehouses</h2><div class="mt-4 grid gap-3 md:grid-cols-3"><input v-model="warehouseForm.code" class="rounded-xl border p-3" placeholder="Code"/><input v-model="warehouseForm.name" class="rounded-xl border p-3" placeholder="Warehouse name"/><input v-model="warehouseForm.city" class="rounded-xl border p-3" placeholder="City"/></div><button @click="createWarehouse" class="mt-3 rounded-xl bg-slate-950 px-5 py-3 font-bold text-white">Add warehouse</button><div class="mt-5 grid gap-3 md:grid-cols-2"><div v-for="w in warehouses" class="rounded-xl border p-4"><b>{{w.name}}</b><p class="text-sm text-slate-500">{{w.code}} · {{w.city||'No city'}}</p></div></div></div>
<div v-if="tab==='Suppliers'" class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-black">Suppliers</h2><div class="mt-4 grid gap-3 md:grid-cols-3"><input v-model="supplierForm.name" class="rounded-xl border p-3" placeholder="Supplier name"/><input v-model="supplierForm.contactName" class="rounded-xl border p-3" placeholder="Contact person"/><input v-model="supplierForm.phone" class="rounded-xl border p-3" placeholder="Phone"/><input v-model="supplierForm.email" class="rounded-xl border p-3" placeholder="Email"/></div><button @click="createSupplier" class="mt-3 rounded-xl bg-slate-950 px-5 py-3 font-bold text-white">Add supplier</button><div class="mt-5 grid gap-3 md:grid-cols-2"><div v-for="s in suppliers" class="rounded-xl border p-4"><b>{{s.name}}</b><p class="text-sm text-slate-500">{{s.contactName||'No contact'}} · {{s.phone||'No phone'}}</p></div></div></div>
</section></template>
<script>
import api from '../services/api'
export default{data(){return{tab:'Product',tabs:['Product','Inventory','Brands','Warehouses','Suppliers'],categories:[],brands:[],warehouses:[],suppliers:[],allVariants:[],inventory:[],optionForms:[],variants:[],brandName:'',message:'',busy:false,form:{name:'',categoryId:'',brandId:'',price:0,sku:'',imageUrl:'',description:''},warehouseForm:{code:'',name:'',city:''},supplierForm:{name:'',contactName:'',phone:'',email:''},adjust:{warehouseId:'',variantId:'',type:'receive',quantity:1,note:''}}},async mounted(){await this.load()},methods:{async load(){const [c,b,w,s,i]=await Promise.all([api.get('/categories'),api.get('/brands'),api.get('/warehouses'),api.get('/suppliers'),api.get('/inventory')]);this.categories=c.data.data||[];this.brands=b.data.data||[];this.warehouses=w.data.data||[];this.suppliers=s.data.data||[];this.inventory=i.data.data||[];const ps=await api.get('/products',{params:{limit:100}});this.allVariants=(ps.data.data||[]).flatMap(p=>(p.variants||[]).map(v=>({...v,product:p})))},async loadCategoryAttributes(){this.optionForms=[];if(!this.form.categoryId)return;const r=await api.get('/attributes/categories/'+this.form.categoryId);this.optionForms=(r.data.data||[]).map(x=>({attributeId:x.attribute.id,name:x.attribute.name,sample:(x.attribute.values||[]).map(v=>v.label||v.value).slice(0,4).join(', '),valuesText:(x.attribute.values||[]).map(v=>v.label||v.value).join(', '),isVariant:x.isVariant}))},generateVariants(){const groups=this.optionForms.filter(x=>x.isVariant&&x.valuesText.trim()).map(x=>({attributeId:x.attributeId,name:x.name,values:x.valuesText.split(',').map(v=>v.trim()).filter(Boolean)}));let combos=[[]];for(const g of groups)combos=combos.flatMap(c=>g.values.map(value=>[...c,{attributeId:g.attributeId,value}]));this.variants=combos.map((combo,i)=>({label:combo.map(x=>x.value).join(' / ')||'Default',sku:(this.form.sku||'SKU')+'-'+String(i+1).padStart(3,'0'),price:Number(this.form.price||0),warehouseId:this.warehouses[0]?.id||'',quantity:0,options:combo.map(x=>{const rule=this.optionForms.find(o=>o.attributeId===x.attributeId);const raw=(rule.valuesText.split(',').map(v=>v.trim()).find(v=>v.toLowerCase()===x.value.toLowerCase())||x.value);return{attributeId:x.attributeId,attributeValueId:null,valueLabel:raw}})}))},async createProduct(){this.message='';this.busy=true;try{const attrPayload=[];for(const o of this.optionForms){if(!o.valuesText.trim())continue;for(const val of o.valuesText.split(',').map(v=>v.trim()).filter(Boolean))attrPayload.push({attributeId:o.attributeId,textValue:val})}const variants=this.variants.length?this.variants:[{sku:this.form.sku||'SKU-'+Date.now().toString(36),price:this.form.price,options:[],inventory:this.warehouses[0]?[{warehouseId:this.warehouses[0].id,quantity:0}]:[]}];for(const v of variants){v.inventory=v.warehouseId?[{warehouseId:v.warehouseId,quantity:Number(v.quantity||0)}]:[]}await api.post('/products',{...this.form,attributeValues:attrPayload,variants});this.message='Product created. For select attributes, use the attribute value IDs in a later variant edit; the catalog structure is ready.';this.form={name:'',categoryId:'',brandId:'',price:0,sku:'',imageUrl:'',description:''};this.variants=[];await this.load()}catch(e){this.message=e.response?.data?.message||'Unable to create product'}finally{this.busy=false}},async createBrand(){if(!this.brandName)return;await api.post('/brands',{name:this.brandName});this.brandName='';await this.load()},async createWarehouse(){await api.post('/warehouses',this.warehouseForm);this.warehouseForm={code:'',name:'',city:''};await this.load()},async createSupplier(){await api.post('/suppliers',this.supplierForm);this.supplierForm={name:'',contactName:'',phone:'',email:''};await this.load()},async adjustStock(){await api.post('/inventory/adjust',this.adjust);this.adjust={...this.adjust,quantity:1,note:''};await this.load()}}}
</script>